'use strict';
const groups = [{"id": "centro", "number": "01", "title": "Il centro a piedi", "timing": "UN POMERIGGIO LIBERO QUALSIASI · MEGLIO DOPO LE 17", "color": "pink", "description": "La piazza principale e i tre palazzi che la circondano, poi verso nord lungo Calle 60, da un piccolo parco all’altro.", "sections": [["PLAZA GRANDE", [["cathedral", "Catedral de San Ildefonso", "finita nel 1598 con le pietre dei templi maya di T’hó"], ["gobierno", "Palacio de Gobierno", "i murales di Fernando Castro Pacheco sulla storia dello Yucatán, al piano di sopra", "Gratis."], ["casamontejo", "Casa de Montejo", "la casa della famiglia del conquistador, degli anni 1540, con la facciata scolpita", "Dentro c’è un museo gratuito."], ["walkingtour", "Visita guidata del centro", "si chiede al punto turistico del Centro Cultural Olimpo, in Calle 62", "Ottima per il primo pomeriggio."]]], ["SU PER CALLE 60", [["santalucia", "Parque de Santa Lucía", "portici, ristoranti e le enormi sedie bianche degli innamorati"], ["santaana", "Parque de Santa Ana", "una piazzetta con un mercato, qualche isolato più a nord"]]]], "note": "Le strade con i numeri pari vanno da nord a sud, quelle dispari da est a ovest. Un indirizzo come “Calle 60 x 55 y 57” vuol dire sulla 60, tra la 55 e la 57."}, {"id": "montejo", "number": "02", "title": "Paseo de Montejo", "timing": "UN TARDO POMERIGGIO · O LA DOMENICA MATTINA IN BICI", "color": "green", "description": "La strada carina dei miei appunti: un lungo viale alberato di ville costruite con i soldi dell’henequén intorno al 1900.", "sections": [["IL VIALE", [["paseowalk", "Il Paseo a piedi", "dal Remate di Calle 47 verso nord fino al monumento, circa 2 km"], ["gemelas", "Casas Gemelas", "due ville identiche in stile francese", "Una delle due, Montejo 495, è una casa museo."], ["biciruta", "Biciruta", "la domenica mattina il viale chiude alle auto e si riempie di bici", "Dalle 8 a mezzogiorno. Le bici si noleggiano a un banchetto vicino al Monumento a la Patria."]]], ["MUSEO E MONUMENTO", [["canton", "Palacio Cantón", "il museo regionale di antropologia, nella villa più sontuosa del viale", "Chiuso il lunedì."], ["patria", "Monumento a la Patria", "l’anello di pietra scolpita di Rómulo Rozo, al centro di una rotonda"]]]], "note": "Tra un albero e l’altro c’è poca ombra e il ritorno è lungo. All’andata o al ritorno conviene un autobus o un Uber."}, {"id": "evenings", "number": "03", "title": "Sere in piazza", "timing": "DOPO CENA · TUTTO GRATIS", "color": "blue", "description": "Quasi ogni sera la città organizza qualcosa di gratuito. Ogni spettacolo dura circa un’ora.", "sections": [["A INIZIO SETTIMANA", [["vaqueria", "Vaquería", "il lunedì alle 21: la jarana ballata dal balletto folcloristico della città", "Sotto i portici del Palacio Municipal, in Plaza Grande."], ["videomapping", "Video mapping sulla Casa de Montejo", "il mercoledì alle 20:30: la fondazione della città proiettata sulla facciata"], ["serenata", "Serenata Yucateca", "il giovedì alle 21 nel Parque de Santa Lucía: trii di trova, poesia e danza", "Si fa ogni settimana dal 1965. Per trovare posto a sedere, arrivare mezz’ora prima."]]], ["IL FINE SETTIMANA", [["poktapok", "Pok ta Pok", "il venerdì alle 20 davanti alla cattedrale: il gioco della palla maya, colpita con i fianchi", "Alcuni programmi dicono sabato. Controllare il programma della settimana.", [["Yucatán Today · gli eventi gratuiti della settimana", "https://yucatantoday.com/en/events"]]], ["nochemexicana", "Noche Mexicana", "il sabato alle 20 al Remate de Paseo de Montejo: mariachi, balli e bancarelle di cibo"], ["domingo", "Mérida en Domingo", "la domenica da metà mattina in Plaza Grande: bancarelle di artigianato, cibo e musica tutto il giorno", "Restare fino a sera: la domenica la gente del posto balla in piazza."]]]], "note": "Giorni e luoghi cambiano spesso. Controllare il programma della Semana Meridana quando arriviamo."}, {"id": "markets", "number": "04", "title": "Mercati e il museo maya", "timing": "DUE MATTINE · I MERCATI SONO MEGLIO PRESTO", "color": "pink", "description": "Il grande mercato di tutti i giorni, uno piccolo di quartiere e il museo da vedere prima delle rovine.", "sections": [["MERCATI", [["lucasgalvez", "Mercado Lucas de Gálvez", "il mercato principale: habanero, paste di spezie chiamate recados, frutta e amache", "A fine mattinata fa caldo ed è affollato. Portare banconote piccole."], ["santiago", "Mercado de Santiago", "un mercatino su una bella piazza, a ovest del centro", "Famoso per i banchi della colazione."]]], ["MUSEO", [["granmuseo", "Gran Museo del Mundo Maya", "il grande museo maya moderno, nella zona nord della città", "Chiuso il martedì. Dal centro ci si arriva in autobus o in Uber. Meglio prima di Chichén Itzá e Uxmal."]]]], "note": "Diversi musei chiudono il lunedì, il Gran Museo il martedì."}, {"id": "work", "number": "05", "title": "Alla scrivania", "timing": "LE MATTINE DEI GIORNI FERIALI", "color": "blue", "description": "Tre coworking in centro e due caffè dove si lavora bene.", "sections": [["COWORKING", [["conexion60", "Conexión60", "nel complesso Paseo 60, Calle 60 n. 346, al terzo e quarto piano", "Quello che usa la maggior parte di chi lavora da remoto. Pass giornaliero 200–220 pesos, dalle 8 alle 18, con caffè, cabine per le chiamate e internet veloce.", [["Yucatán Today · coworking a Mérida", "https://yucatantoday.com/en/blog/coworking-merida-prices-services"]]], ["chenomadas", "Che Nómadas Mérida", "Calle 62 n. 433 angolo 51: l’ostello Che, con una sala coworking e la piscina", "Il Che di Puerto Escondido ci era piaciuto. La sala è gratis per gli ospiti; per chi non dorme lì chiedere in reception se c’è un pass, perché le fonti non sono d’accordo.", [["Che Hostels · Mérida", "https://hostelche.com.mx/en/merida-en/"]]], ["iwanttoco", "I Want to CO", "uno spazio più piccolo ed economico vicino a Santiago", "Tariffa giornaliera sui 100 pesos, secondo una guida per nomadi digitali. Controllare prima di andarci."]]], ["CAFFÈ CON WIFI", [["voltacafe", "Voltacafé", "tavoli grandi e wifi veloce"], ["estacion72", "Estación 72", "un caffè rilassato con un buon wifi"]]]], "note": "Coworking e caffè non contano per i progressi: spuntali se ti va."}, {"id": "food", "number": "06", "title": "Mangiare e bere", "timing": "QUANDO ABBIAMO FAME", "color": "green", "description": "La lista dei desideri dello Yucatán, i miei vecchi appunti e i due ristoranti salvati sulla mia mappa.", "sections": [["CUCINA YUCATECA", [["cochinita", "Cochinita pibil", "maiale con achiote e arancia amara, cotto a lungo in una buca; si mangia in tacos e tortas", "Qui è la colazione del fine settimana: ai banchi del mercato finisce entro tarda mattinata."], ["trapiche", "El Trapiche", "dai miei appunti: cucina tipica yucateca vicino alla piazza principale"], ["chayamaya", "La Chaya Maya", "il posto classico per tutto il menù regionale"], ["yucatanlist", "Il resto della lista", "sopa de lima, panuchos, salbutes, papadzules, poc chuc e queso relleno"]]], ["SALVATI SULLA MIA MAPPA", [["huniik", "Huniik", "Calle 60 tra la 45 e la 47, vicino a Santa Ana: un piccolo ristorante con menù degustazione", "Serve la prenotazione."], ["mora", "MORA", "ristorante indiano a San Carlos, nella zona nord", "Dal centro ci vuole un taxi."]]], ["DOLCE E FREDDO", [["colon", "Sorbetería Colón", "dai miei appunti: sorbetti e gelati dal 1907", "Sul Paseo de Montejo e in Plaza Grande."], ["marquesitas", "Marquesitas", "una cialda croccante arrotolata, ripiena di formaggio Edam, dai carretti della sera"], ["limonada", "Limonada de coco", "quella con i punti interrogativi nella mia lista"], ["manifesto", "Manifesto", "torrefazione"], ["bengala", "Bengala Kaffeehaus", "caffè vicino a Santa Lucía"]]]], "note": "Cibo e bevande non contano per i progressi."}, {"id": "uxmal", "number": "SAT", "title": "Uxmal", "timing": "IL NOSTRO PRIMO SABATO · RITORNO NEL TARDO POMERIGGIO", "color": "pink", "weekend": true, "description": "L’altra grande città maya, circa 80 km a sud, con molta meno gente. Qui la pietra è scolpita più finemente che a Chichén Itzá.", "table": {"caption": "Come arrivare a Uxmal", "map": "Mappa", "days": [["Autobus · solo Uxmal", [["Circa 1 ora e mezza", "Autobus dal terminal TAME", "Calle 69 tra la 68 e la 70. La mattina parte verso le 6, le 9 e a mezzogiorno; il ritorno verso le 15 e le 17. Chiedere conferma al terminal il giorno prima.", "Ferma sulla strada, davanti all’ingresso", "Uxmal"]]], ["Auto o autista · con un cenote", [["Tutto il giorno", "Uxmal, poi Cenote X’batun", "X’batun è salvato sulla mia mappa: un cenote aperto vicino a San Antonio Mulix, sulla stessa strada del ritorno. Non ci arriva nessun autobus, quindi serve un’auto a noleggio o un autista per la giornata.", "Circa 1 ora e un quarto da Mérida", "Cenote X’batun"]]]]}, "sections": [["PIRAMIDE E QUADRILATERO", [["adivino", "Pirámide del Adivino", "la Piramide dell’Indovino: fianchi arrotondati, dritta davanti appena si entra", "Non si può salire."], ["monjas", "Cuadrángulo de las Monjas", "quattro lunghi edifici intorno a un cortile, coperti di mosaici di pietra"]]], ["PIÙ IN ALTO", [["gobernador", "Palacio del Gobernador", "una facciata lunga quasi 100 m, su una piattaforma tutta sua"], ["granpiramide", "La Gran Pirámide", "l’unica su cui si può ancora salire, dalla scalinata nord", "Da lassù si vede tutto il sito."]]]], "note": "L’ingresso è in due biglietti da pagare a due sportelli. Per gli stranieri, nel 2026, le fonti danno cifre da 500 a 720 pesos: portare 750 a testa in contanti. Apre alle 8; ultimo ingresso verso le 16. Lo spettacolo serale di luci è sospeso.", "link": ["Yucatán Today · Uxmal", "https://yucatantoday.com/en/blog/uxmal"]}, {"id": "cenotes", "number": "SAT", "title": "Una giornata di cenote", "timing": "IL NOSTRO SECONDO SABATO · IN ACQUA TUTTO IL GIORNO", "color": "green", "weekend": true, "description": "La giornata intera dedicata ai cenote. Tre modi per farla, tutti a circa un’ora a sud-est di Mérida, tra Cuzamá e Homún.", "table": {"caption": "Tre modi per fare i cenote", "map": "Mappa", "days": [["Cuzamá", [["2–3 ore sul posto", "Con il carretto a cavallo", "Il classico: un carretto su vecchi binari stretti ci porta a tre cenote e aspetta mentre facciamo il bagno. Si paga a carretto, quindi in due costa come in quattro.", "Colectivo da Calle 67 tra la 50 e la 52", "Cuzamá Yucatán"]]], ["Homún", [["Quanto vogliamo", "In mototaxi", "Il paese accanto ha più cenote tra cui scegliere. Un mototaxi ci porta in giro a prezzo fisso e ogni cenote ha un piccolo ingresso.", "Colectivo dallo stesso angolo", "Homún Yucatán"]]], ["Santa Bárbara", [["Circa 3 ore sul posto", "Un biglietto, tre cenote", "La versione organizzata, a Homún: tre cenote con un solo biglietto, raggiunti in carretto o in bici, con docce e ristorante sul posto.", "A Homún", "Cenotes Santa Bárbara Homún"]]]]}, "sections": [["COME SPOSTARSI", [["cenoteride", "Il tragitto tra un cenote e l’altro", "in carretto, mototaxi o bici, a seconda di quale scegliamo"]]], ["IN ACQUA", [["cenoteswim", "Un bagno in tre cenote", "alcuni a cielo aperto, altri dentro grotte a cui si scende per scale ripide", "Portare costume, asciugamano, scarpette da scoglio e contanti. Niente crema solare in acqua."]]]], "note": "Non ho confermato i prezzi attuali di nessuno dei tre. Gli ultimi colectivos per il ritorno partono a metà pomeriggio: meglio partire presto.", "link": ["Along Dusty Roads · Mérida", "https://www.alongdustyroads.com/posts/2014/4/11/city-guides-merida-mexico"]}, {"id": "chichen", "number": "MAR", "title": "Chichén Itzá e Valladolid", "timing": "UN MARTEDÌ LIBERO · IL COMPLEANNO DI DANIELE", "color": "blue", "weekend": true, "description": "La gita di compleanno: la mattina le rovine famose, poi pranzo e pomeriggio nella cittadina coloniale 40 km più avanti.", "table": {"caption": "Come si svolge la giornata", "map": "Mappa", "days": [["In autobus", [["Circa 2 ore", "Autobus ADO da Mérida", "Partenze verso le 7, le 9 e le 11. Circa 280–320 pesos a tratta; costa meno se si compra qualche giorno prima al terminal. Prendere quello delle 7.", "Ferma all’ingresso del sito", "Chichén Itzá"], ["Circa 45 minuti", "Colectivo per Valladolid", "Dalle rovine partono furgoncini condivisi per Valladolid a circa 40 pesos, che fermano a un isolato dalla stazione degli autobus.", "Dalla strada davanti al sito", "Valladolid Yucatán"], ["Circa 2 ore e un quarto", "ADO di ritorno a Mérida", "Gli autobus viaggiano fino a sera. Comprare il biglietto di ritorno appena arrivati a Valladolid.", "Dalla stazione ADO di Valladolid", "ADO Valladolid Yucatán"]]], ["Auto o autista", [["Tutto il giorno", "Auto a noleggio o autista", "La stessa giornata senza orari: circa 1 ora e mezza fino alle rovine in autostrada, 40 minuti fino a Valladolid e meno di 2 ore per tornare.", "Da Mérida", "Chichén Itzá"]]]]}, "sections": [["LE ROVINE", [["castillo", "El Castillo", "la piramide di Kukulcán: 365 gradini, uno per ogni giorno dell’anno", "Non si può salire."], ["ballcourt", "Il Grande Campo della Palla", "il più grande della Mesoamerica; un battito di mani fa eco da un capo all’altro"], ["sacredcenote", "Il Cenote Sacro", "in fondo a una strada bianca rialzata; per le offerte, non per nuotare"], ["caracol", "El Caracol", "l’osservatorio rotondo"]]], ["VALLADOLID", [["vplaza", "La piazza principale e San Servacio", "palme, sedie bianche degli innamorati e la chiesa con le due torri"], ["frailes", "Calzada de los Frailes", "la strada più bella: case colorate e negozietti, fino al convento"], ["sanbernardino", "Convento de San Bernardino", "un convento francescano degli anni 1550 che sembra una fortezza"], ["lomitos", "A pranzo: lomitos de Valladolid", "il piatto della città, maiale in salsa di pomodoro; anche la salsiccia longaniza è di qui"]]]], "note": "Nel 2026 l’ingresso a Chichén Itzá per gli stranieri è di 697 pesos a testa, in due biglietti da pagare a due sportelli. Aperto dalle 8 alle 17, ultimo ingresso alle 16. Cappello, acqua e contanti."}];

const optional = [["celestun", "Celestún", "in barca tra le mangrovie fino ai fenicotteri, circa 1 ora e mezza a ovest", "Nella nostra lista dei fine settimana. I fenicotteri aumentano da dicembre a marzo. Le barche si pagano a barca, quindi conviene dividerla: i tour chiedono circa 500 pesos a testa in contanti. Gli autobus partono dal terminal Noreste più o meno ogni ora.", [["Yucatán Today · Celestún", "https://yucatantoday.com/en/celestun"]]], ["elcuyo", "El Cuyo", "un villaggio di mare sulla costa nord: spiaggia larga, kitesurf e fenicotteri nei dintorni", "Nella nostra lista dei fine settimana, ma è lontano: circa 3 ore e mezza in auto, di più in autobus con cambio a Tizimín. Servono una o due notti, quindi ci prenderebbe un intero fine settimana.", [["Yucatán Today · El Cuyo", "https://yucatantoday.com/en/blog/el-cuyo"]]], ["xbatun", "Cenote X’batun", "salvato sulla mia mappa: un cenote aperto vicino a San Antonio Mulix, a sud della città", "Più comodo in auto, tornando da Uxmal."], ["ikkil", "Cenote Ik Kil", "il cenote aperto a 3 km da Chichén Itzá, con le liane che scendono fino all’acqua", "Solo se vogliamo fare un bagno il giorno del compleanno: 10 minuti di taxi dalle rovine, ma toglierebbe tempo a Valladolid."], ["zaci", "Cenote Zací", "un cenote in mezzo a Valladolid, a pochi isolati dalla piazza", "Per un tuffo veloce il giorno del compleanno. Controllare prima che sia aperto."], ["izamal", "Izamal", "la città dipinta di giallo, con un convento costruito su una piattaforma maya; circa 1 ora e un quarto a est"], ["progreso", "Progreso", "la spiaggia più vicina, con un molo lunghissimo; meno di un’ora a nord in autobus"], ["campeche", "Campeche", "salvata sulla mia mappa: un porto fortificato di case color pastello, a circa 2 ore e mezza di autobus"]];
const KEY='frolicking-nicky-merida-v1';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPTIONAL_IDS=new Set(["conexion60", "voltacafe", "estacion72", "cochinita", "trapiche", "chayamaya", "yucatanlist", "huniik", "mora", "colon", "marquesitas", "limonada", "manifesto", "bengala", "lomitos", "chenomadas", "iwanttoco"]);
const countedIds=()=>groups.filter(()=>true).flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0]))).filter(id=>!OPTIONAL_IDS.has(id));
function item(row,extra=false) {const [id,title,desc,note,links]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}${links&&links.length?`<span class="fn-task-links">${links.map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l)} ↗︎</a>`).join('')}</span>`:''}</span></label>`;}
const PHOTOS={"centro": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Palacio_de_Gobierno_del_Estado_de_Yucat%C3%A1n_01.jpg/1280px-Palacio_de_Gobierno_del_Estado_de_Yucat%C3%A1n_01.jpg", "Il cortile verde a portici del Palacio de Gobierno di Mérida", 1280, 853, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Palacio_de_Gobierno_del_Estado_de_Yucat%C3%A1n_01.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Portales_del_Parque_de_Santa_Luc%C3%ADa_en_M%C3%A9rida%2C_Yucat%C3%A1n_%2801%29.jpg/1280px-Portales_del_Parque_de_Santa_Luc%C3%ADa_en_M%C3%A9rida%2C_Yucat%C3%A1n_%2801%29.jpg", "I portici lungo il Parque de Santa Lucía a Mérida", 1280, 960, "Inri", "CC0", "https://commons.wikimedia.org/wiki/File:Portales_del_Parque_de_Santa_Luc%C3%ADa_en_M%C3%A9rida,_Yucat%C3%A1n_(01).jpg"]]], "montejo": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Casas_C%C3%A1mara%2C_Casa_del_Minarete_-_Axtel_-_Paseo_de_Montejo%2C_M%C3%A9rida%2C_Yucat%C3%A1n.jpg/1280px-Casas_C%C3%A1mara%2C_Casa_del_Minarete_-_Axtel_-_Paseo_de_Montejo%2C_M%C3%A9rida%2C_Yucat%C3%A1n.jpg", "Le ville gemelle in stile francese sul Paseo de Montejo", 1280, 857, "Andreita Pech", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Casas_C%C3%A1mara,_Casa_del_Minarete_-_Axtel_-_Paseo_de_Montejo,_M%C3%A9rida,_Yucat%C3%A1n.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Monumento_a_la_Patria%2C_M%C3%A9rida_Yucatan_Mexico_2018.jpg/1280px-Monumento_a_la_Patria%2C_M%C3%A9rida_Yucatan_Mexico_2018.jpg", "Il Monumento a la Patria, in pietra scolpita, al centro della sua rotonda", 1280, 960, "amanderson2", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Monumento_a_la_Patria,_M%C3%A9rida_Yucatan_Mexico_2018.jpg"]]], "evenings": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Bailando_la_Jarana_-_Plaza_Grande%2C_M%C3%A9rida%2C_Yucat%C3%A1n_Dic_2019.jpg/1280px-Bailando_la_Jarana_-_Plaza_Grande%2C_M%C3%A9rida%2C_Yucat%C3%A1n_Dic_2019.jpg", "Ballerini in abiti bianchi ricamati che ballano la jarana sotto i portici di Plaza Grande", 1280, 853, "Bruno Rijsman", "CC BY-SA 2.0", "https://commons.wikimedia.org/wiki/File:Bailando_la_Jarana_-_Plaza_Grande,_M%C3%A9rida,_Yucat%C3%A1n_Dic_2019.jpg"]]], "chichen": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Chichen-Itza-Castillo-Seen-From-East.JPG/1280px-Chichen-Itza-Castillo-Seen-From-East.JPG", "El Castillo, la piramide a gradoni di Chichén Itzá, sotto un cielo di nuvole", 1280, 960, "Bjørn Christian Tørrissen", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Chichen-Itza-Castillo-Seen-From-East.JPG"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Valladolid_calle.jpg/1280px-Valladolid_calle.jpg", "Una strada di case colorate a Valladolid", 1280, 847, "Haakon S. Krohn", "CC BY 4.0", "https://commons.wikimedia.org/wiki/File:Valladolid_calle.jpg"], ["https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Iglesia_de_San_Servacio%2C_Valladolid%2C_Yucatan%2C_Mexico_Marzo_2021.jpg/1280px-Iglesia_de_San_Servacio%2C_Valladolid%2C_Yucatan%2C_Mexico_Marzo_2021.jpg", "La chiesa di San Servacio dietro le palme della piazza principale di Valladolid", 1280, 960, "Sharon Hahn Darlin", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Iglesia_de_San_Servacio,_Valladolid,_Yucatan,_Mexico_Marzo_2021.jpg"]]], "uxmal": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Pyramid_of_the_Magician_%28Pir%C3%A1mide_del_Adivino%29%2C_Zona_Arqueol%C3%B3gica_de_Uxmal%2C_Yucatan%2C_Mexico.jpg/1280px-Pyramid_of_the_Magician_%28Pir%C3%A1mide_del_Adivino%29%2C_Zona_Arqueol%C3%B3gica_de_Uxmal%2C_Yucatan%2C_Mexico.jpg", "La Piramide dell’Indovino di Uxmal, dai fianchi arrotondati, incorniciata dai rami", 1280, 960, "Sharon Hahn Darlin", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Pyramid_of_the_Magician_(Pir%C3%A1mide_del_Adivino),_Zona_Arqueol%C3%B3gica_de_Uxmal,_Yucatan,_Mexico.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Nunnery_Quadrangle%2C_Uxmal_Maya_site%2C_Yucatan%2C_June_2024.jpg/1280px-Nunnery_Quadrangle%2C_Uxmal_Maya_site%2C_Yucatan%2C_June_2024.jpg", "I lunghi edifici scolpiti del Quadrilatero delle Monache a Uxmal", 1280, 720, "Eden, Janine and Jim", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Nunnery_Quadrangle,_Uxmal_Maya_site,_Yucatan,_June_2024.jpg"]]], "cenotes": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Truk%2C_Cenotes%2C_Cuzam%C3%A1_-_Tranvias_de_Caballo.jpg/1280px-Truk%2C_Cenotes%2C_Cuzam%C3%A1_-_Tranvias_de_Caballo.jpg", "Un cavallo che tira un carretto sui binari stretti verso i cenote di Cuzamá", 1280, 853, "Gildardo Sánchez", "CC BY 2.0", "https://commons.wikimedia.org/wiki/File:Truk,_Cenotes,_Cuzam%C3%A1_-_Tranvias_de_Caballo.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Cenote_en_Yucat%C3%A1n.jpg/1280px-Cenote_en_Yucat%C3%A1n.jpg", "Radici d’albero che scendono fino all’acqua blu di un cenote", 1280, 960, "Andrea 4164", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Cenote_en_Yucat%C3%A1n.jpg"]]]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a></figure>`;
const muertosTable=(t,gid)=>{const pick=0;return `<div class="fn-plan-tabs" role="tablist" aria-label="${esc(t.caption)}">${t.days.map(([day],i)=>`<button type="button" role="tab" id="fn-plan-tab-${gid}-${i}" aria-controls="fn-plan-day-${gid}-${i}" aria-selected="${i===pick}" tabindex="${i===pick?0:-1}">${esc(day.split(' · ')[0])}</button>`).join('')}</div>${t.days.map(([day,rows],i)=>`<div class="fn-plan-panel" role="tabpanel" id="fn-plan-day-${gid}-${i}" aria-labelledby="fn-plan-tab-${gid}-${i}"${i===pick?'':' hidden'}>${day.includes(' · ')?`<p class="fn-plan-sub">${esc(day.split(' · ').slice(1).join(' · '))}</p>`:''}<ol class="fn-plan-stops">${rows.map(([when,plan,what,where,q,url])=>`<li${/★/.test(plan)?' class="fn-plan-star"':''}><span class="fn-plan-when">${esc(when)}</span><div><p class="fn-plan-name">${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(plan)} ↗︎</a>`:esc(plan)}</p><p class="fn-plan-what">${esc(what)}</p><p class="fn-plan-where">${esc(where)} <a class="fn-plan-map" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(q)}" target="_blank" rel="noopener noreferrer">${esc(t.map)}</a></p></div></li>`).join('')}</ol></div>`).join('')}`;};
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Completamento della sezione"></span></div>${g.table?`<div class="fn-plan-wrap">${muertosTable(g.table,g.id)}</div>`:''}<div class="outing-body fn-split-body"${g.sections.length?'':' hidden'}>${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r,OPTIONAL_IDS.has(r[0]))).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelectorAll('.fn-plan-tabs').forEach(list=>{const tabs=[...list.querySelectorAll('[role=tab]')];const show=(tab,focus)=>{tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!on;});if(focus)tab.focus();};tabs.forEach((b,i)=>{b.addEventListener('click',()=>show(b));b.addEventListener('keydown',e=>{const n={ArrowRight:i+1,ArrowLeft:i-1,Home:0,End:tabs.length-1}[e.key];if(n===undefined)return;e.preventDefault();show(tabs[(n+tabs.length)%tabs.length],true);});});});
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
function update(announce=false){const mainIds=countedIds();const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`su ${mainIds.length} posti e momenti`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const inactive=false;const ids=g.sections.flatMap(s=>s[1].map(r=>r[0])).filter(id=>!OPTIONAL_IDS.has(id));document.querySelector('#count-'+g.id).hidden=!ids.length;document.querySelector('#count-'+g.id).textContent=inactive?"Alternativa: non conta nella checklist":`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=[...optional.map(r=>r[0]),...OPTIONAL_IDS].filter(id=>checked[id]===true).length;document.querySelector('#extra-count').textContent=`${extra} ${extra===1?'tappa facoltativa fatta':'tappe facoltative fatte'}`;document.querySelector('#save-note').textContent=storageOK?'Progressi salvati su questo dispositivo.':'Le spunte funzionano qui, ma in questo browser il salvataggio non è disponibile.';if(announce)document.querySelector('#announcement').textContent=`${done} su ${mainIds.length} voci principali completate. ${extra} tappe facoltative fatte.`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
